import { expect, test } from "@playwright/test";
import { loadFixtures } from "../lib/fixtures";
import { expectFieldValue, monitorPage, normalizedPath } from "../lib/page-health";
import { CORE_ROUTES, EXTENDED_ROUTES, type RouteScope, ROUTES, ROUTE_SETS } from "../lib/routes";

type RouteCheckMode = "smoke" | "strict";

const routeScope = (process.env.E2E_ROUTE_SCOPE ?? "all") as RouteScope;
const selectedRoutes = ROUTE_SETS[routeScope];
const routeCheck = (process.env.E2E_ROUTE_CHECK ?? "strict") as RouteCheckMode;

if (!selectedRoutes) {
  throw new Error(`Unknown E2E_ROUTE_SCOPE "${routeScope}". Use all, core, or extended.`);
}
if (!["smoke", "strict"].includes(routeCheck)) {
  throw new Error(`Unknown E2E_ROUTE_CHECK "${routeCheck}". Use smoke or strict.`);
}

test("route table has unique entries", () => {
  expect(ROUTES.length).toBeGreaterThan(0);
  expect(new Set(ROUTES.map(r => r.file)).size).toBe(ROUTES.length);
  expect(CORE_ROUTES.length).toBeGreaterThan(0);
  expect(EXTENDED_ROUTES.length).toBeGreaterThan(0);
  expect(CORE_ROUTES.length + EXTENDED_ROUTES.length).toBe(ROUTES.length);
});

for (const route of selectedRoutes) {
  test.describe(route.anonymous ? "anonymous" : "admin", () => {
    if (route.anonymous) {
      test.use({ storageState: { cookies: [], origins: [] } });
    }

    test(`[route] ${route.file}`, async ({ page }) => {
      const f = loadFixtures();
      const health = monitorPage(page);

      await page.goto(route.path(f));

      if (routeCheck === "strict") {
        for (const text of route.texts(f)) {
          await expect(page.getByText(text, { exact: false }).filter({ visible: true }).first(), `visible text "${text}"`).toBeVisible();
        }
        for (const value of route.values?.(f) ?? []) {
          await expectFieldValue(page, value);
        }
      }
      else {
        await expect(page.locator("body")).toBeVisible();
        await expect.poll(() => page.locator("body").innerText()).not.toBe("");
      }

      const expected = route.finalPath?.(f) ?? route.path(f);
      if (expected instanceof RegExp) {
        expect(normalizedPath(page)).toMatch(expected);
      }
      else {
        expect(normalizedPath(page)).toBe(expected);
      }

      await health.assertHealthy();
    });
  });
}
import { expect, test } from "@playwright/test";
import { loadFixtures, NAMES } from "../../lib/fixtures";
import { uniqueName, visibleText } from "../../lib/ui";

test.describe("recipes", () => {
  test("[flow] open a recipe from the recipe list", async ({ page }) => {
    const f = loadFixtures();
    await page.goto(`/g/${f.groupSlug}`);
    await page.getByRole("link", { name: NAMES.recipe }).first().click();
    await expect(page).toHaveURL(new RegExp(`/g/${f.groupSlug}/r/${f.recipeSlug}/?$`));
    await expect(visibleText(page, NAMES.ingredient)).toBeVisible();
    await expect(visibleText(page, NAMES.instruction)).toBeVisible();
  });

  test("[flow] search narrows the recipe list", async ({ page }) => {
    const f = loadFixtures();
    await page.goto(`/g/${f.groupSlug}`);
    await expect(page.getByRole("link", { name: NAMES.recipe })).toBeVisible();
    await page.getByRole("textbox", { name: "Search..." }).fill("Garden Salad");
    await expect(page.getByRole("link", { name: NAMES.recipe2 })).toBeVisible();
    await expect(page.getByRole("link", { name: NAMES.recipe })).toHaveCount(0);
  });

  test("[flow] create a recipe by name", async ({ page }) => {
    const f = loadFixtures();
    const name = uniqueName("E2E Flow Soup");
    await page.goto(`/g/${f.groupSlug}/r/create/new`);
    await page.getByRole("textbox", { name: "Recipe Name" }).fill(name);
    await page.getByRole("main").getByRole("button", { name: "Create", exact: true }).click();
    await expect(page).toHaveURL(new RegExp(`/g/${f.groupSlug}/r/e2e-flow-soup-[a-z0-9-]+`));

    await page.goto(`/g/${f.groupSlug}`);
    await expect(page.getByRole("link", { name })).toBeVisible();
  });

  test("[flow] comment on a recipe and see it after reload", async ({ page }) => {
    const f = loadFixtures();
    const comment = uniqueName("E2E comment");
    await page.goto(`/g/${f.groupSlug}/r/${f.recipe2Slug}`);
    await page.getByRole("textbox", { name: "Join the Conversation" }).fill(comment);
    await page.getByRole("button", { name: "Submit" }).click();
    await expect(visibleText(page, comment)).toBeVisible();
    await page.reload();
    await expect(visibleText(page, comment)).toBeVisible();
  });
});
